extras = {'people':'叔叔','social':'反对 同意 喜欢','home':'电脑','travel':'电梯','time':'迟到','places':'底 省','school':'错误 回答 年级','work':'打电话 电子邮件 短信 互联网 密码 上网 手机 网站 信封 占线','culture':'参加 声音','descriptions':'错 剩','ideas':'表示 叫 经历 事情','numbers':'四','patterns':'专门'}
groups = [(slug,title,desc,heads+' '+extras.get(slug,'')) for slug,title,desc,heads in groups]

if __name__ == '__main__':
    path = Path(__file__).resolve().parents[1] / 'public/data/chinese/hsk-1-4.json'
    data = json.loads(path.read_text(encoding='utf8'))
    words = {w['hanzi']:w for w in data['words']}
    assigned = {}; themes = []
    for number,(slug,title,description,heads) in enumerate(groups,1):
        ids = []
        for head in heads.split():
            if head not in words: continue
            assert head not in assigned, (head,assigned.get(head),title)
            assigned[head] = title; ids.append(words[head]['id'])
        themes.append(dict(id=f'hsk-theme-{number:02}',number=number,name=title,description=description,wordIds=ids))
    missing = [h for h in words if h not in assigned]
    print('Counts:',[(t['name'],len(t['wordIds'])) for t in themes]); print('Unassigned:', ' '.join(missing))
    if not missing:
        data['themes'] = themes
        path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
